import React from 'react';
import { Routes, Route } from 'react-router-dom';
import Home from './pages/Home/Home'; // Path dhyan se check karein
import TruckBookingPage from './pages/Booking/TruckBookingPage';

const AppRoutes = () => {
    return (
        <Routes>
            {/* 1. Default path check karein (Sabse zaruri) */}
            <Route path="/" element={<Home />} />

            {/* 2. Truck Booking path */}
            <Route path="/book-truck" element={<TruckBookingPage />} />

            {/* Agar koi route match na ho toh 404 ya Home par bhejein */}
            <Route path="*" element={<Home />} />
        </Routes>
    );
};

export default AppRoutes;
